            self.create_tree(nodes)

    def create_tree(self, nodes):
        node_map = {node[0]: node[1:] for node in nodes}

        for value, children in node_map.items():
            child_values = [child for child in children if child in node_map]
            if child_values:
                children_nodes = [TreeNode(node_map[child]) for child in child_values]
                self.root = TreeNode(value, children_nodes)
                break

    def __repr__(self):
        return f'Tree({self.root})'

