class TicTacToe:
    def __init__(self):
        self.board = np.zeros((3, 3))
        self.player = 1
        self.n_players = 2

    def is_terminal(self):
        for row in self.board:
            if np.all(row == 1) or np.all(row == 2):
                return True
        for col in range(3):
            if np.all(self.board[:, col] == 1) or np.all(self.board[:, col] == 2):
                return True
        if np.all(np.diag(self.board) == 1) or np.all(np.diag(np.fliplr(self.board)) == 1):
            return True
        if np.all(np.diag(self.board) == 2) or np.all(np.diag(np.fliplr(self.board)) == 2):
            return True
        if np.any(self.board == 0):
            return False
        return True

    def step(self, action):
        if self.board[action // 3, action % 3]!= 0:
            raise ValueError("Invalid action")
        self.board[action // 3, action % 3] = self.player
        self.player = 3 - self.player  # Switch player

        reward = 0
        if self.is_terminal():
            if np.all(self.board == 1):
                reward = 1
            elif np.all(self.board == 2):
                reward = -1
            else:
                reward = 0.5  # Draw

        return self.board.flatten(), reward, self.is_terminal()

    def reset(self):
        self.board = np.zeros((3, 3))
        self.player = 1
        return self.board.flatten()


class QLearningAgent:
    def __init__(self, alpha=0.1, gamma=0.9, epsilon=0.1):
        self.alpha = alpha
        self.gamma = gamma
        self.epsilon = epsilon
        self.q_table = np.zeros((3, 3, 3, 3))

    def get_action(self, state):
        if np.random.random() < self.epsilon:
            return np.random.randint(0, 9)
        return np.argmax(self.q_table[tuple(state)])

    def update_q_table(self, state, action, next_state, reward):
        max_q_value = np.max(self.q_table[tuple(next_state)])
        target = reward + self.gamma * max_q_value
        current_q_value = self.q_table[tuple(state)][action]
        self.q_table[tuple(state)][action] += self.alpha * (target - current_q_value)


