        new_user = {
            'id': len(users) + 1,
            'name': data['name'],
            'email': data['email']
        }
        users.append(new_user)
        return new_user, 201

    def put(self, user_id):
        user = next((u for u in users if u['id'] == user_id), None)
        if user:
            data = request.get_json()
            user.update(data)
            return user
        else:
            return {'message': 'User not found'}, 404

    def delete(self, user_id):
        user = next((u for u in users if u['id'] == user_id), None)
        if user:
            users.remove(user)
            return {'message': 'User deleted'}
        else:
            return {'message': 'User not found'}, 404

