class ComplexNumber:
    """
    This class represents a complex number with methods for addition, subtraction, multiplication, and division.
    """

    def __init__(self, real: float, imag: float):
        """
        Initialize a new ComplexNumber object with the given real and imaginary parts.

        Args:
            real (float): The real part of the complex number.
            imag (float): The imaginary part of the complex number.
        """
        self.real = real
        self.imag = imag

    def __add__(self, other):
        """
        Add this complex number with another complex number or a real number.

        Args:
            other: The other complex number or real number to add with this complex number.

        Returns:
            A new ComplexNumber object representing the result of the addition.
        """
        if isinstance(other, ComplexNumber):
            return ComplexNumber(self.real + other.real, self.imag + other.imag)
        else:
            return ComplexNumber(self.real + other, self.imag)

    def __sub__(self, other):
        """
        Subtract another complex number or a real number from this complex number.

        Args:
            other: The other complex number or real number to subtract from this complex number.

        Returns:
            A new ComplexNumber object representing the result of the subtraction.
        """
        if isinstance(other, ComplexNumber):
            return ComplexNumber(self.real - other.real, self.imag - other.imag)
        else:
            return ComplexNumber(self.real - other, self.imag)

    def __mul__(self, other):
        """
        Multiply this complex number with another complex number or a real number.

        Args:
            other: The other complex number or real number to multiply with this complex number.

        Returns:
            A new ComplexNumber object representing the result of the multiplication.
        """
        if isinstance(other, ComplexNumber):
            real = self.real * other.real - self.imag * other.imag
            imag = self.real * other.imag + self.imag * other.real
            return ComplexNumber(real, imag)
        else:
            return ComplexNumber(self.real * other, self.imag * other)

    def __truediv__(self, other):
        """
        Divide this complex number by another complex number or a real number.

        Args:
            other: The other complex number or real number to divide this complex number by.

        Returns:
            A new ComplexNumber object representing the result of the division.
        """
        if isinstance(other, ComplexNumber):
            denominator = other.real ** 2 + other.imag ** 2
            real = (self.real * other.real + self.imag * other.imag) / denominator
            imag = (self.imag * other.real - self.real * other.imag) / denominator
            return ComplexNumber(real, imag)
        else:
            return ComplexNumber(self.real / other, self.imag / other)

    def __str__(self):
        """
        Return a string representation of this complex number in the format "a + bi".

        Returns:
            A string representation of this complex number.
        """
        if self.imag >= 0:
            return f"{self.real} + {self.imag}i"
        else:
            return f"{self.real} - {abs(self.imag)}i"
